/* Table extension styles using shadcn CSS variables */

/* ── Hover overlay ── */
.ext-table-overlay {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  overflow: visible;
}

/* ── Table node view wrapper ──
   Tiptap's Table View renders a <div class="tableWrapper"> around the
   <table>. We use it as the hover container (grips stay visible anywhere
   inside it) and as the horizontal scroll container so wide tables with
   many columns scroll instead of overflowing the content area. */
.tableWrapper {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 0.375rem;
  scrollbar-width: thin;
}

/* Columns must keep their widths when a column is added/removed. If the table
   fills the container (`width: 100%` + auto columns), the browser re-distributes
   the fixed width across more columns and they all shrink. Instead we size the
   table to its columns (`width: max-content`) so each column keeps its declared
   width and an inserted column extends the row width — the `.tableWrapper`
   scroll container above then shows the horizontal scrollbar instead. */
.tableWrapper > table {
  border-collapse: collapse;
  table-layout: fixed;
  width: max-content;
}

/* Stable default width for columns until the user resizes them (resize writes
   an inline width, which overrides this). Prevents fixed-layout auto columns
   from collapsing to 0 / splitting the table width on insert. */
.tableWrapper > table > colgroup > col {
  width: 8rem;
}

/* ── Cell borders & header row ── */
.ProseMirror table {
  border-collapse: collapse;
  margin: 0;
  overflow: hidden;
  position: relative;
}

.ProseMirror td,
.ProseMirror th {
  border: 1px solid var(--border);
  padding: 0.5rem 0.75rem;
  vertical-align: top;
  text-align: left;
  min-width: 80px;
  position: relative;
}

.ProseMirror th {
  background: var(--muted);
  font-weight: 600;
}

.ProseMirror .selectedCell {
  background: var(--accent);
}

.ext-table-control {
  position: absolute;
  z-index: 2;
  animation: ext-table-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-table-control--column {
  transform-origin: top center;
}

.ext-table-control--row {
  transform-origin: center left;
}

.ext-table-grip {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.1rem;
  height: 1.1rem;
  padding: 0;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--muted-foreground);
  cursor: pointer;
  touch-action: none;
  box-shadow: none;
  transition:
    background-color 150ms ease-out,
    border-color 150ms ease-out,
    box-shadow 150ms ease-out,
    color 150ms ease-out;
}

.ext-table-grip::before {
  content: "";
  position: absolute;
  inset: -0.35rem;
  border-radius: calc(var(--radius) - 2px);
}

.ext-table-grip > svg {
  position: absolute;
  inset: 0;
  margin: auto;
  width: 0.75rem;
  height: 0.75rem;
  flex-shrink: 0;
  opacity: 0;
  scale: 0.6;
  transition:
    opacity 150ms ease-out,
    scale 150ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.ext-table-grip-stroke {
  position: absolute;
  inset: 0;
  margin: auto;
  border-radius: 1px;
  background: var(--muted-foreground);
  opacity: 0.6;
  pointer-events: none;
  transition: opacity 150ms ease-out;
}

.ext-table-grip-stroke--column {
  width: 14px;
  height: 3px;
}

.ext-table-grip-stroke--row {
  width: 3px;
  height: 14px;
}

.ext-table-grip--row > svg {
  rotate: 90deg;
}

.ext-table-grip:hover,
.ext-table-grip[data-state="open"] {
  background: var(--popover);
  border-color: var(--border);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

.ext-table-grip:hover > svg,
.ext-table-grip[data-state="open"] > svg,
.ext-table-grip:focus-visible > svg {
  opacity: 1;
  scale: 1;
}

.ext-table-grip--row:hover > svg,
.ext-table-grip--row[data-state="open"] > svg,
.ext-table-grip--row:focus-visible > svg {
  rotate: 90deg;
  scale: 1;
}

.ext-table-grip:hover .ext-table-grip-stroke,
.ext-table-grip[data-state="open"] .ext-table-grip-stroke {
  opacity: 0;
}

.ext-table-grip:active {
  transform: scale(0.92);
}

.ext-table-grip:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.ext-table-add {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 4px);
  background: var(--popover);
  color: var(--popover-foreground);
  animation: ext-table-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.ext-table-add > svg {
  width: 0.875rem;
  height: 0.875rem;
  flex-shrink: 0;
}

.ext-table-add:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-table-add:active {
  transform: scale(0.95);
}

@keyframes ext-table-pop-in {
  from {
    opacity: 0;
    scale: 0.9;
  }
  to {
    opacity: 1;
    scale: 1;
  }
}

/* ── Toolbar ── */
.ext-table-toolbar-popover {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  padding: 0.5rem;
}

.ext-table-toolbar-item-spacer {
  flex: 1;
}

.ext-table-toolbar-label {
  padding: 0.25rem 0.5rem 0.375rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--muted-foreground);
}

.ext-table-grid {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 11rem;
}

.ext-table-grid-popover {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.ext-table-grid-row {
  display: flex;
  gap: 0.25rem;
}

.ext-table-grid-cell {
  width: 1rem;
  height: 1rem;
  border: 1px solid var(--border);
  border-radius: 2px;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    border-color 100ms ease-out;
}

.ext-table-grid-cell--selected {
  border-color: var(--primary);
  background: var(--primary);
}

.ext-table-grid-result {
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
  padding: 0.25rem 0.5rem;
  text-align: center;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--muted-foreground);
}

/* ── Column resize (prosemirror-tables) ── */
.ProseMirror .column-resize-handle {
  position: absolute;
  right: -2px;
  top: 0;
  bottom: -2px;
  width: 1px;
  background-color: color-mix(in srgb, var(--foreground) 25%, transparent);
  pointer-events: none;
}

.ProseMirror .column-resize-dragging .column-resize-handle {
  background-color: var(--primary);
}

.ProseMirror.resize-cursor {
  cursor: col-resize;
}

/* Extensions UI primitives using shadcn CSS variables */

@keyframes ext-pop-in {
  from {
    opacity: 0;
    translate: 0 0.25rem;
    scale: 0.95;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* ── Button ── */
.ext-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 2px);
  background: transparent;
  color: inherit;
  font-size: 0.8125rem;
  font-family: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    border-color 150ms ease-out,
    transform 100ms ease-out;
}

.ext-btn > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-btn--icon {
  width: 2rem;
  padding: 0;
}

.ext-btn--icon-sm {
  width: 1.75rem;
  padding: 0;
}

.ext-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

.ext-btn:active {
  transform: scale(0.96);
}

.ext-btn:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-btn--active {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn--danger {
  color: var(--destructive, #ef4444);
}

.ext-btn--danger:hover {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

/* ── Dropdown ── */
.ext-dropdown-content {
  position: relative;
  min-width: 10rem;
  padding: 0.25rem;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-dropdown-item {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.375rem 0.5rem;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--popover-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.ext-dropdown-item > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.ext-dropdown-pill--visible {
  opacity: 1;
}

.ext-dropdown-item:hover,
.ext-dropdown-item:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-dropdown-item:active {
  transform: scale(0.98);
}

.ext-dropdown-item:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-dropdown-item--danger {
  color: var(--destructive, #ef4444);
}

.ext-dropdown-item--danger:hover,
.ext-dropdown-item--danger:focus-visible {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

.ext-dropdown-separator {
  height: 1px;
  background: var(--border);
  margin: 0.25rem 0;
}

/* ── Popover ── */
.ext-popover-content {
  position: relative;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* ── Separator ── */
.ext-separator {
  flex-shrink: 0;
  background: var(--border);
}

.ext-separator--horizontal {
  height: 1px;
  margin: 0.25rem 0;
}

.ext-separator--vertical {
  width: 1px;
  height: 1rem;
  align-self: center;
  margin: 0 0.25rem;
}

/* ── Input ── */
.ext-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background: var(--background);
  color: var(--foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-input::placeholder {
  color: var(--muted-foreground);
}

.ext-input:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ring) 30%, transparent);
}

/* ── Tabs ── */
.ext-tabs {
  display: flex;
  flex-direction: column;
}

.ext-tabs-list {
  display: flex;
  gap: 0.125rem;
  width: fit-content;
  padding: 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
}

.ext-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border: none;
  border-radius: calc(var(--radius) - 6px);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out;
}

.ext-tabs-trigger > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-tabs-trigger:hover,
.ext-tabs-trigger:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-tabs-trigger--active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.ext-tabs-content {
  padding-top: 0.5rem;
}
